//! 🧪️ Native member checkpoint erasure preserves actual authored allocations and the original decoder through full closure.
use super::*;
use store::SpaceMember;

fn probe(store:&store::ConfigStore<State,Mutation>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,expected:bool){
 type Probe=store::os_vcs::io::binary::checkpoint_identity::original::pending::OriginalPendingEditIds;let mut original=None;turn(caller,decoder,TURN,|cx|{let d=OriginalConstructionDemand{items:1,copy_bytes:size_of::<Probe>(),capacity_bytes:0,release_bytes:0,depth:1};admit_original_construction(cx,&mut original,d,|_|Ok((Probe::probe(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))?;Ok(())});let probe=original.as_mut().unwrap();
 for index in 0..262144{if let Some(found)=probe.pending_found(){assert_eq!(found,expected);break}let d=store.native_checkpoint_probe_demands(probe).unwrap();assert_eq!(d.capacity_bytes,0);let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:d.depth};for axis in [0,1,4]{let mut denied=exact;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,_=>denied.maximum_depth=0};turn(caller,decoder,denied,|cx|{let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:0,release_bytes:0,depth:d.depth},|_|Ok(((),store.advance_native_checkpoint_probe(probe,denied)?)))?;Ok(())});assert_eq!(caller.receipt(),Default::default());assert_eq!(store.native_checkpoint_probe_demands(probe).unwrap(),d);}turn(caller,decoder,exact,|cx|{let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:0,release_bytes:0,depth:d.depth},|_|Ok(((),store.advance_native_checkpoint_probe(probe,exact)?)))?;Ok(())});assert!(index<262143);}
 for index in 0..262144{if probe.terminal_is_empty(){break}turn(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=probe.close_demands(4096)?;close_original_retained_step(cx,d,|g|probe.close_step(g))?;Ok(())}));assert!(index<262143);}
 turn(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=RetirementDemand{copy_bytes:size_of::<Option<Probe>>(),depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{original.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(())}));
}

#[test]fn original_member_vcs_checkpoint_preserves_the_typed_command_and_original_caller(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for cut in law["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain([None]){
  let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};probe(&store,&mut caller,&mut decoder,false);let result=crate::original_replay_publication::prepare_report(&mut store,&mut caller,&mut decoder);crate::original_stream_abort::close_report_fixture(result,&mut caller,&mut decoder);probe(&store,&mut caller,&mut decoder,true);
  let message=law["message"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize);let message_pointer=message.as_ptr();let authors=vec![store::Author{id:law["author"]["id"].as_str().unwrap().into(),name:law["author"]["name"].as_str().unwrap().into(),avatar:None}];let authors_pointer=authors.as_ptr();let mut request=Some(store::ArtifactNativeVcsRequest::CommitCheckpoint{message:Some(message),authors});let mut source=None;let birth=store.member_native_vcs_capture_demands();
  for axis in [0,1,2,4]{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=birth.copy_bytes-1,2=>denied.maximum_capacity_bytes=birth.capacity_bytes-1,_=>denied.maximum_depth=0};turn(&mut caller,&mut decoder,denied,|cx|{assert!(!store.admit_member_native_vcs_command(&mut request,cx,&mut source)?);Ok(())});assert!(source.is_none());let store::ArtifactNativeVcsRequest::CommitCheckpoint{message,authors}=request.as_ref().unwrap()else{unreachable!()};assert_eq!(message.as_ref().unwrap().as_ptr(),message_pointer);assert_eq!(authors.as_ptr(),authors_pointer);}
  turn(&mut caller,&mut decoder,g,|cx|{assert!(store.admit_member_native_vcs_command(&mut request,cx,&mut source)?);Ok(())});assert!(request.is_none());let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,g,|cx|{assert!(store.advance_member_native_vcs_command(source.as_mut().unwrap().as_mut(),cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());
  for index in 0..262144{if cut==Some(index)||source.as_ref().unwrap().phase()==store::ArtifactNativeVcsPhase::AwaitingAck{break}turn(&mut caller,&mut decoder,g,|cx|store.advance_member_native_vcs_command(source.as_mut().unwrap().as_mut(),cx));assert!(index<262143);}
  if cut.is_none(){let mut result=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(store.take_member_native_vcs_result(source.as_mut().unwrap().as_mut(),cx,&mut result)?);Ok(())});assert_eq!(result.unwrap().kind,store::ArtifactNativeVcsKind::CommitCheckpoint);turn(&mut caller,&mut decoder,g,|cx|{assert!(store.ack_member_native_vcs_command(source.as_mut().unwrap().as_mut(),cx)?);Ok(())});let parts=store.parts_ref();let checkpoint=parts.log.envelope.vcs.checkpoints.get(0).unwrap();assert_eq!(checkpoint.message.as_ref().unwrap().as_ptr(),message_pointer);assert_eq!(checkpoint.authors.as_ptr(),authors_pointer);assert_eq!(serde_json::from_str::<String>(&serde_json::to_string(checkpoint.message.as_ref().unwrap()).unwrap()).unwrap(),law["message"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize));assert_eq!(parts.log.envelope.transitions.len(),1);assert_eq!(parts.wire.original_outbox.len(),1);probe(&store,&mut caller,&mut decoder,false);}else{caller.cancel().cancel_now();}
  for index in 0..262144{if source.as_ref().unwrap().terminal_is_empty(){break}let d=store.member_native_vcs_close_demands(source.as_ref().unwrap().as_ref(),4096).unwrap();let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in 0..5{let mut denied=exact;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};turn(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|{assert!(!store.close_member_native_vcs_command(source.as_mut().unwrap().as_mut(),cx)?);Ok(())}));assert_eq!(store.member_native_vcs_close_demands(source.as_ref().unwrap().as_ref(),4096).unwrap(),d);}turn(&mut caller,&mut decoder,exact,|cx|cx.with_original_retirement(|cx|store.close_member_native_vcs_command(source.as_mut().unwrap().as_mut(),cx)));assert!(index<262143,"original member VCS close stalled {d:?}");}
  let d=source.as_ref().unwrap().release_demands();turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|_|{source.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }
}
